opener(5, 'תרגילים מסכמים למפגש 2', 'שאלת החלק: האם אתם יודעים לבנות את החישוב לבד?',
       ['תרגילים מתמטיים, עם בדיקה אוטומטית', 'תרגילים בגיליון Excel שבתוך השקף', 'בכל תרגיל: רמז, תזכורת נוסחה, פתרון חלקי ופתרון מלא'], 25, note='<b>מה כבר תרגלנו:</b> חוזה אקדמה, באקסל, בסוף מפגש 1. <b>כאן:</b> אופציות, מכפיל ומנוף, החומר החדש של מפגש 2.')

SOLVE('t-1', 'תרגיל 1: Long Put', 'תרגיל 1: קונה אופציית מכר (Long Put)',
      'משקיע מחזיק מניה שנסחרת היום ב-85 ש״ח, וחושש שמחירה ירד. לכן הוא רכש אופציית מכר (Put) על המניה, במחיר מימוש (K) של 80 ש״ח, ושילם עבורה פרמיה (p) של 5 ש״ח. המכפיל (Multiplier) הוא 1. ענו על ארבעת הסעיפים.',
      [('א. מה הרווח מהאופציה, אם מחיר המניה בפקיעה הוא 72 ש״ח?', 3, 0.001), ('ב. מהי נקודת האיזון (Break-even), כלומר המחיר שבו אין רווח ואין הפסד?', 75, 0.001), ('ג. באיזה מחיר בפקיעה הרווח הוא בדיוק 12 ש״ח?', 63, 0.001), ('ד. מהו הרווח המרבי האפשרי מהאופציה?', 75, 0.001)],
      ['תזרים ב-Put: $max(K − S_{T}, 0)$.', 'בנקודת האיזון הרווח אפס.', 'הרווח מרבי כשהמניה צונחת לאפס.'], 'רווח = $max(K − S_{T}, 0) − p$. נקודת איזון: $K − p$. רווח מרבי: $K − p$, כשהמניה צונחת לאפס.',
      ['<b>א.</b> $max(80 − 72, 0) − 5 = 3$', '<b>ב.</b> $80 − 5 = 75$', '<b>ג.</b> $80 − S_{T} − 5 = 12$, ולכן $S_{T} = 63$', '<b>ד.</b> $80 − 0 − 5 = 75$'])
SOLVE('t-2', 'תרגיל 2: Short Call', 'תרגיל 2: כותב אופציית רכש (Short Call)',
      'משקיעה מעריכה שמניה, שנסחרת היום ב-58 ש״ח, לא תעלה הרבה בחודשים הקרובים. לכן היא כתבה (מכרה) אופציית רכש (Call) על המניה, במחיר מימוש (K) של 60 ש״ח, וקיבלה פרמיה (c) של 4 ש״ח. המכפיל (Multiplier) הוא 1. ענו על ארבעת הסעיפים.',
      [('א. מה הרווח או ההפסד שלה, אם מחיר המניה בפקיעה הוא 70 ש״ח?', -6, 0.001), ('ב. מה הרווח או ההפסד שלה, אם מחיר המניה בפקיעה הוא 55 ש״ח?', 4, 0.001), ('ג. מהי נקודת האיזון (Break-even)?', 64, 0.001), ('ד. מהו הרווח המרבי שהיא יכולה להשיג?', 4, 0.001)],
      ['הכותבת מקבלת את הפרמיה בכל מקרה.', 'אם הקונה מממש, היא מוכרת ב-K מה ששווה יותר.'], 'רווח = $c − max(S_{T} − K, 0)$. נקודת איזון: $K + c$. רווח מרבי: הפרמיה $c$.',
      ['<b>א.</b> $4 − (70 − 60) = −6$', '<b>ב.</b> לא ממומשת: $4 − 0 = 4$', '<b>ג.</b> $60 + 4 = 64$', '<b>ד.</b> הפרמיה: 4'])
SOLVE('t-4', 'תרגיל 3: מכפיל במדד', 'תרגיל 3: Call על מדד, עם מכפיל (Multiplier)',
      'משקיע מעריך שמדד מניות יעלה, ולכן רכש 3 אופציות רכש (Call) על המדד. מחיר המימוש (K) הוא 4,300 נקודות, הפרמיה (c) היא 40 נקודות לאופציה, והמדד נמדד בנקודות, ובחוזה הזה כל נקודה במדד שווה 50 ש״ח: זה המכפיל (Multiplier). בפקיעה המדד עומד על 4,420 נקודות. ענו על ארבעת הסעיפים.',
      [('א. כמה שקלים שילם היום עבור שלוש האופציות?', 6000, 0.5), ('ב. מה התזרים בפקיעה, בנקודות, לאופציה אחת?', 120, 0.001), ('ג. מה הרווח בשקלים, על שלוש האופציות יחד?', 12000, 0.5), ('ד. מהי נקודת האיזון, ברמת המדד?', 4340, 0.001)],
      ['קודם בנקודות, לאופציה אחת. רק בסוף כופלים במכפיל ובמספר האופציות.'], 'עלות היום = $c$ × מכפיל × מספר. תזרים לאופציה = $max(S_{T} − K, 0)$. רווח (ש״ח) = (תזרים − $c$) × מכפיל × מספר. נקודת איזון: $K + c$.',
      ['<b>א.</b> $40 × 50 × 3 = 6,000$', '<b>ב.</b> $4,420 − 4,300 = 120$', '<b>ג.</b> $(120 − 40) × 50 × 3 = 12,000$', '<b>ד.</b> $4,300 + 40 = 4,340$'])
SOLVE('t-5', 'תרגיל 4: Put על דולר', 'תרגיל 4: Put על הדולר, מכפיל 10,000',
      'יצואן ישראלי יקבל דולרים בעוד חודש, וחושש שהדולר ייחלש. לכן הוא קנה 10 אופציות מכר (Put) על הדולר. מחיר המימוש (K) הוא 3.60 ש״ח לדולר, הפרמיה (p) היא 0.05 ש״ח לדולר, וכל אופציה מתייחסת ל-10,000 דולר: זה המכפיל (Multiplier). בפקיעה השער הוא 3.40. ענו על שלושת הסעיפים.',
      [('א. כמה שקלים שילם היום עבור עשר האופציות?', 5000, 0.5), ('ב. מה הרווח בשקלים, על עשר האופציות יחד?', 15000, 0.5), ('ג. מהי נקודת האיזון, בשער הדולר?', 3.55, 0.0001)],
      ['התזרים לדולר אחד: $3.60 − 3.40$.', 'בסוף כופלים ב-10,000 וב-10.'], 'עלות היום = $p$ × מכפיל × מספר. רווח (ש״ח) = ($max(K − S_{T}, 0) − p$) × מכפיל × מספר. נקודת איזון: $K − p$.',
      ['<b>א.</b> $0.05 × 10,000 × 10 = 5,000$', '<b>ב.</b> $(3.60 − 3.40 − 0.05) × 10,000 × 10 = 15,000$', '<b>ג.</b> $3.60 − 0.05 = 3.55$'])
SOLVE('t-6', 'תרגיל 5: מנוף', 'תרגיל 5: מנוף (Leverage) בחוזה עתידי (Futures)',
      'משקיעה מעריכה שמדד מניות יעלה. היא קונה (Long) חוזה עתידי (Futures) אחד על המדד, שעומד היום על 3,000 נקודות. המדד נמדד בנקודות, ובחוזה הזה כל נקודה במדד שווה 50 ש״ח: זה המכפיל (Multiplier). היא מפקידה ביטחונות (Margin) של 15,000 ש״ח. למחרת המדד עולה ב-1%. ענו על ארבעת הסעיפים.',
      [('א. מהי החשיפה שלה, בשקלים?', 150000, 1), ('ב. מהו המנוף (Leverage)?', 10, 0.001), ('ג. מה הרווח שלה, בשקלים?', 1500, 0.5), ('ד. מהי התשואה על הביטחונות, באחוזים?', 10, 0.001)],
      ['חשיפה בשקלים: רמת המדד בנקודות כפול המכפיל, כלומר כפול השקלים שכל נקודה שווה.', 'מנוף: חשיפה ÷ ביטחונות.'], 'חשיפה (ש״ח) = נקודות המדד × מכפיל (ש״ח לנקודה). מנוף = חשיפה ÷ ביטחונות. רווח = חשיפה × שינוי במדד. תשואה על הביטחונות = רווח ÷ ביטחונות.',
      ['<b>א.</b> $3,000 × 50 = 150,000$', '<b>ב.</b> $150,000 ÷ 15,000 = 10$', '<b>ג.</b> $150,000 × 1% = 1,500$', '<b>ד.</b> $1,500 ÷ 15,000 = 10%$'])

